<script setup lang="ts">
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useFitness } from './store'
import { dayOn, setCount, type TrainingRecord } from '../../../shared/fitness'
import DesignArt from './DesignArt.vue'
import ExerciseImage from './ExerciseImage.vue'
import AppIcon from '../components/AppIcon.vue'
const props=defineProps<{date:string}>(),fs=useFitness(),router=useRouter(),saving=ref(false),celebrating=ref(false)
const day=computed(()=>fs.loaded?dayOn(fs.data,props.date):undefined),resting=computed(()=>!day.value||day.value.type==='休息'),record=computed(()=>fs.data.records.find(r=>r.date===props.date&&(r.id==='home-complete-'+props.date||r.title===day.value?.title))),completed=computed(()=>!!record.value&&!saving.value),names=computed(()=>day.value?.items.map(i=>fs.exercise(i.exerciseId)?.name||'已删除动作')||[])
async function complete(){
 if(saving.value||record.value||!day.value||resting.value)return
 saving.value=true
 const date=props.date,d=day.value,r:TrainingRecord={id:'home-complete-'+date,date,title:d.title,type:d.type,minutes:null,notes:'已在主页确认当日训练完成。计划动作：'+(names.value.join('、')||d.title)+'。实际动作、重量、次数及用时可另行补充。',tags:'今日完成',source:'主页完成',items:[],updated:new Date().toISOString()}
 fs.data.records.push(r)
 try{if(await fs.save()){celebrating.value=true}else fs.data.records=fs.data.records.filter(x=>x.id!==r.id)}finally{saving.value=false}
}
function viewRecord(){void router.push({path:'/fitness',query:{view:'calendar',record:record.value?.id}})}
</script>
<template><section class="today-fitness" :class="{'is-complete':completed,'is-celebrating':celebrating,'is-resting':resting}" :aria-busy="saving"><header><h2><AppIcon name="fitness"/>今日健身</h2><button class="text-link" @click="router.push('/fitness')">查看计划 ↗</button></header>
<div v-if="!fs.loaded" class="today-fitness-loading">正在读取今日安排…</div><Transition name="daily-state" mode="out-in"><div v-if="fs.loaded" :key="completed?'done':resting?'rest':'ready'" class="daily-content"><div class="daily-scene"><div class="daily-orbit"/><span class="daily-eyebrow">{{ completed?'TODAY, WELL DONE':resting?'RECOVER & RECHARGE':'YOUR DAILY RHYTHM' }}</span><div class="daily-hero-copy"><span class="daily-status"><i/>{{ completed?'今天的努力，已记下':resting?'恢复，也是进步':'按自己的节奏来' }}</span><h3>{{ completed?'今日训练，完成。':resting?'给身体，充充电。':day?.title }}</h3><p>{{ completed?'把这一份坚持，留给未来的自己。':resting?'好好休息，为下一次训练蓄力。':day?.items.length+' 个计划动作 · '+setCount(day?.items||[])+' 组' }}</p></div><DesignArt :kind="resting&&!completed?'note-character':'hero'" class="daily-mascot"/><span v-if="completed" class="daily-seal"><AppIcon name="check" :size="20"/></span><div v-if="celebrating&&completed" class="daily-confetti" aria-hidden="true"><i v-for="n in 12" :key="n" :style="{'--i':n}"/></div></div>
<template v-if="!completed&&!resting"><div class="daily-action-preview"><span class="daily-section-label">今天练这些</span><div class="daily-action-strip"><div v-for="item in day?.items.slice(0,3)" :key="item.exerciseId"><ExerciseImage :image="fs.exercise(item.exerciseId)?.image" :alt="fs.exercise(item.exerciseId)?.name"/><span>{{ fs.exercise(item.exerciseId)?.name||'已删除动作' }}</span></div><button v-if="(day?.items.length||0)>3" @click="router.push('/fitness')">+{{ (day?.items.length||0)-3 }}<small>查看全部</small></button></div></div><footer><button class="daily-complete-button" :disabled="saving" @click="complete"><span>{{ saving?'正在保存记录…':'✓ 今日训练已完成' }}</span><span v-if="!saving">↗</span></button><p>完成后保存训练摘要，实际数据可稍后补充。</p></footer></template>
<div v-else-if="completed" class="daily-success"><div class="daily-saved"><span class="daily-saved-icon">✓</span><div><b>已同步到训练记录</b><p>{{ record?.title }} · {{ date.slice(5).replace('-','.') }}</p></div><span class="daily-saved-badge">已完成</span></div><button class="daily-record-button" @click="viewRecord">查看训练记录 <span>→</span></button><p class="daily-footnote">已保存完成摘要，动作明细与用时可以随时补充。</p></div><footer v-else><button class="daily-record-button" @click="router.push('/fitness')">{{ day?'看看接下来的安排':'安排我的训练' }} <span>→</span></button><p>不必每天用力，恢复也有自己的节奏。</p></footer></div></Transition><span class="daily-announcer" aria-live="polite">{{ completed?'今日训练已完成，已同步到训练记录。':'' }}</span></section></template>
<style scoped>
.today-fitness{position:relative;display:flex;flex-direction:column;min-height:350px;color:var(--ink);overflow:hidden}.today-fitness header{flex-shrink:0}.daily-content{display:flex;flex-direction:column;flex:1;gap:18px}.daily-scene{position:relative;isolation:isolate;overflow:hidden;border-radius:18px;min-height:180px;padding:23px;background:linear-gradient(125deg,#e9f7f2bb,#f1f9f8aa);flex:1;display:flex;flex-direction:column;justify-content:center}.daily-eyebrow{font-size:9px;letter-spacing:2px;color:#89b2a4;position:relative;z-index:1}.daily-hero-copy{position:relative;z-index:1;max-width:67%;margin-top:17px}.daily-status{font-size:11px;color:#75a495;display:flex;align-items:center;gap:6px}.daily-status i{width:5px;height:5px;border-radius:50%;background:#66b99b}.daily-hero-copy h3{font-size:clamp(19px,1.25vw,28px);line-height:1.5;letter-spacing:-.5px;color:#305e54;margin:7px 0!important;font-weight:650;overflow-wrap:anywhere}.daily-hero-copy p{font-size:11px;line-height:1.8;color:#85a79e;margin:0}.daily-mascot{position:absolute;right:-12px;bottom:5px;width:43%;height:145px;object-fit:contain;filter:drop-shadow(0 10px 10px #4884730c);transition:transform .35s}.daily-scene:hover .daily-mascot{transform:translateY(-5px) rotate(3deg)}.daily-orbit{position:absolute;width:230px;height:230px;border:1px solid #ffffffc9;border-radius:50%;right:-65px;top:-45px;box-shadow:0 0 0 28px #ffffff27,0 0 0 56px #ffffff18;z-index:-1}.daily-section-label{font-size:10px;color:var(--secondary);letter-spacing:.5px}.daily-action-strip{display:flex;gap:8px;margin-top:10px;align-items:stretch}.daily-action-strip>div{display:flex;flex:1;min-width:0;gap:6px;align-items:center;border:1px solid var(--line);border-radius:10px;padding:7px;background:#ffffff50}.daily-action-strip img{width:32px;height:36px;object-fit:contain;border-radius:6px;flex-shrink:0}.daily-action-strip>div>span{font-size:10px;line-height:1.6;overflow-wrap:anywhere;color:var(--secondary)}.daily-action-strip>button{border:0;border-radius:9px;padding:7px;color:#6a9c8c;background:#e9f3ee80;flex-shrink:0;font-size:14px;cursor:pointer}.daily-action-strip small{display:block;font-size:8px;margin-top:4px}.today-fitness footer{margin-top:auto}.daily-complete-button,.daily-record-button{display:flex;align-items:center;justify-content:space-between;gap:10px;width:100%;padding:13px 17px;border:0;border-radius:11px;font:inherit;font-size:12px;cursor:pointer;transition:transform .2s,box-shadow .2s}.daily-complete-button{color:#fff;background:linear-gradient(115deg,#24a886,#0e8064);box-shadow:0 5px 12px #1585611c}.daily-complete-button:hover{transform:translateY(-2px);box-shadow:0 8px 17px #15856129}.daily-complete-button:active{transform:scale(.98)}.daily-complete-button:disabled{opacity:.65;cursor:wait}.today-fitness footer>p,.daily-footnote{font-size:9px;line-height:1.8;color:var(--secondary);margin:9px 0 0;text-align:center}.daily-record-button{background:#edf7f2;color:#468b74;border:1px solid #d7eee3}.daily-record-button:hover{background:#e3f3eb;transform:translateY(-2px)}.is-complete .daily-scene{background:linear-gradient(120deg,#e6f6ec,#f8faed);min-height:185px}.is-complete .daily-hero-copy h3{color:#44785b}.daily-seal{position:absolute;right:17px;top:16px;background:#fff9;border:1px solid #ffffffbd;display:grid;place-items:center;width:32px;height:32px;border-radius:50%;color:#53a783}.daily-saved{display:flex;align-items:center;gap:11px;padding:0 2px 17px}.daily-saved-icon{display:grid;place-items:center;width:32px;height:32px;border-radius:50%;background:#e6f3ec;color:#4b9f7b}.daily-saved b{font-size:12px;font-weight:550;color:#4e7969}.daily-saved p{margin:5px 0 0;font-size:10px;color:var(--secondary)}.daily-saved-badge{margin-left:auto;font-size:9px;color:#68a082;background:#eaf4ee;padding:5px 9px;border-radius:6px;white-space:nowrap}.daily-confetti{position:absolute;inset:0;pointer-events:none;overflow:hidden}.daily-confetti i{position:absolute;left:calc(8% + var(--i)*7%);top:38%;width:5px;height:9px;background:#75bd9c;border-radius:2px;animation:daily-confetti 1.2s calc(var(--i)*.035s) both ease-out}.daily-confetti i:nth-child(3n){background:#c3b3e7}.daily-confetti i:nth-child(3n + 1){background:#efcd8f}.is-celebrating .daily-mascot{animation:daily-jump .75s .1s both}.daily-state-enter-active,.daily-state-leave-active{transition:opacity .2s,transform .2s}.daily-state-enter-from{opacity:0;transform:translateY(8px)}.daily-state-leave-to{opacity:0;transform:translateY(-5px)}.daily-announcer{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.today-fitness button:focus-visible{outline:2px solid var(--primary);outline-offset:3px}@keyframes daily-confetti{0%{opacity:0;transform:translateY(10px) rotate(0)}20%{opacity:1}100%{opacity:0;transform:translateY(-95px) rotate(180deg)}}@keyframes daily-jump{0%,100%{transform:translateY(0)}40%{transform:translateY(-18px) rotate(-6deg)}70%{transform:translateY(2px) rotate(3deg)}}@media(max-width:1300px){.daily-action-strip>div{flex-direction:column;align-items:flex-start}.daily-scene{padding:18px}.daily-hero-copy{max-width:68%}}@media(prefers-reduced-motion:reduce){.today-fitness *{animation:none!important;transition:none!important}}:global([data-theme=dark]) .daily-scene{background:linear-gradient(125deg,#24453a,#293e3b)}:global([data-theme=dark]) .daily-hero-copy h3{color:#bee1cf}:global([data-theme=dark]) .daily-record-button{background:#28493c;color:#b3d5c4;border-color:#365647}
